parameters.jsCode:
const input = $input.first()?.json;
const body = input?.body || {};
const reservation = body?.reservation;
const user = body?.user || {};
const restaurant = body?.restaurant || {};

if (!reservation) {
  return [{ json: { error: "reservation not found in input", input } }];
}

// DATE
const dateObj = new Date(reservation.date);
const safeDate = isNaN(dateObj.getTime()) ? null : dateObj;
let formattedDate = "Invalid date";
if (safeDate) {
  const dateParts = new Intl.DateTimeFormat("en-GB", {
    weekday: "short",
    day: "2-digit",
    month: "short",
    year: "numeric",
  }).formatToParts(safeDate);
  const getPart = (type) => dateParts.find((p) => p.type === type)?.value || "";
  formattedDate = `${getPart("weekday")}, ${getPart("day")} ${getPart("month")} ${getPart("year")}`;
}

// TIME
let formattedTime = "Invalid time";
if (reservation.time) {
  let timeObj;
  if (typeof reservation.time === "string" && /^\d{1,2}:\d{2}(:\d{2})?$/.test(reservation.time)) {
    const [h, m] = reservation.time.split(":");
    timeObj = new Date(2000, 0, 1, Number(h), Number(m));
  } else {
    timeObj = new Date(reservation.time);
  }
  if (!isNaN(timeObj.getTime())) {
    formattedTime = new Intl.DateTimeFormat("en-US", {
      hour: "numeric",
      minute: "2-digit",
      hour12: true,
    }).format(timeObj);
  }
}

// PEOPLE
const peopleNum = Number(reservation.people);
const formattedPeople =
  Number.isFinite(peopleNum) && peopleNum > 0
    ? `${peopleNum} ${peopleNum === 1 ? "guest" : "guests"}`
    : "Guests not specified";

// DETAILS
const formattedDetails =
  reservation.details && String(reservation.details).trim() !== ""
    ? String(reservation.details).trim()
    : "No details.";

// RESERVATION CODE
const reservationCode = reservation.reservation_code || "Code not available";

return [
  {
    json: {
      // Dados formatados
      formattedDate,
      formattedTime,
      formattedPeople,
      formattedDetails,
      reservationCode,

      // Usuário
      userId: user.id,
      userName: user.name,
      userEmail: user.email,
      userPhone: user.phone,

      // Reserva
      reservationId: reservation.id,
      reservationDate: reservation.date,
      reservationTime: reservation.time,
      reservationPeople: reservation.people,
      reservationStatus: reservation.status,
      reservationDetails: reservation.details,

      // Restaurante
      restaurantId: restaurant.id,
      restaurantName: restaurant.name,
      restaurantEmail: restaurant.email,
      restaurantPhone: restaurant.phone,

      // Management
      managementUrl: body.management_url,
    },
  },
];

